<script setup lang="ts">
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import type { Project } from '~~/shared/types/projects'
import type { InputCard, InputField, InputFieldType, InputAttachment, ProjectInputs } from '~~/shared/types/project-inputs'
import { inputCardWriteSchema } from '~~/shared/utils/project-inputs'
const props=defineProps<{project:Project}>(),auth=useAuthStore(),client=useQueryClient()
const key=computed(()=>['account',auth.user?.id,'project-inputs',props.project.id]),base=computed(()=>`/api/projects/${props.project.id}/input-data`)
const query=useQuery({queryKey:key,queryFn:({signal})=>sharedRequest<ProjectInputs>(base.value,{signal}),retry:false,refetchInterval:30000})
const canEdit=computed(()=>props.project.permission!=='viewer'),search=ref(''),open=ref(false),busy=ref(false),error=ref(''),uploadStatus=ref(''),removeId=ref(''),preview=ref(''),previewName=ref(''),loadingFile=ref('')
const draft=ref({id:'',title:'',description:'',fields:[] as InputField[]}),draftRevision=ref(0),files=ref<File[]>([]),existing=ref<InputAttachment[]>([]),fileInput=ref<HTMLInputElement|null>(null)
const types=[{label:'Текст',value:'text'},{label:'Длинный текст',value:'multiline'},{label:'Ссылка',value:'url'},{label:'Дата',value:'date'},{label:'Число',value:'number'},{label:'Флажок',value:'checkbox'}]
const rows=computed(()=>(query.data.value?.cards??[]).filter(card=>`${card.title} ${card.description} ${card.fields.map(f=>f.label+' '+f.value).join(' ')} ${card.attachments.map(f=>f.name).join(' ')}`.toLocaleLowerCase('ru').includes(search.value.toLocaleLowerCase('ru').trim())))
const date=(value:string)=>new Intl.DateTimeFormat('ru-RU',{dateStyle:'medium',timeZone:'Europe/Moscow'}).format(new Date(value))
const size=(value:number)=>value>=1048576?`${(value/1048576).toFixed(1)} МБ`:`${Math.ceil(value/1024)} КБ`
const image=(file:InputAttachment)=>['image/png','image/jpeg','image/gif','image/webp'].includes(file.type)
function edit(card?:InputCard){error.value='';files.value=[];draftRevision.value=query.data.value?.revision??0;draft.value=card?{id:card.id,title:card.title,description:card.description,fields:structuredClone(toRaw(card.fields))}:{id:crypto.randomUUID(),title:'',description:'',fields:[]};existing.value=card?.attachments??[];open.value=true}
function addField(){draft.value.fields.push({id:crypto.randomUUID(),label:'',type:'text',value:''})}
function fieldType(field:InputField,type:InputFieldType){field.type=type;field.value=type==='checkbox'?'false':''}
function chooseFiles(event:Event){const chosen=Array.from((event.target as HTMLInputElement).files??[]);if(chosen.some(f=>f.size>20971520||!f.size)){error.value='Выберите непустые файлы до 20 МБ каждый.'}else if(existing.value.length+files.value.length+chosen.length>50){error.value='В карточке можно сохранить до 50 файлов.'}else{files.value.push(...chosen);error.value=''};(event.target as HTMLInputElement).value=''}
async function refreshRelated(){await client.invalidateQueries({queryKey:['account',auth.user?.id,'project-process-map',props.project.id]})}
async function save(){
 if(busy.value)return
 const parsed=inputCardWriteSchema.safeParse({...draft.value,revision:draftRevision.value})
 if(!parsed.success){error.value=parsed.error.issues[0]?.message||'Проверьте поля карточки';return}
 const user=auth.user?.id;busy.value=true;error.value=''
 try{
  let result=await sharedRequest<ProjectInputs>(base.value,{method:'PUT',body:parsed.data})
  if(auth.user?.id!==user)return
  client.setQueryData(key.value,result);draftRevision.value=result.revision
  while(files.value.length){const file=files.value[0]!,form=new FormData();form.append('cardId',draft.value.id);form.append('revision',String(result.revision));form.append('file',file);uploadStatus.value=`Загружаем ${file.name}…`;result=await sharedRequest<ProjectInputs>(`${base.value}/upload`,{method:'POST',body:form});if(auth.user?.id!==user)return;files.value.shift();draftRevision.value=result.revision;existing.value=result.cards.find(c=>c.id===draft.value.id)?.attachments??[];client.setQueryData(key.value,result)}
  open.value=false;await refreshRelated()
 }catch(e:any){if(auth.user?.id===user){error.value=e?.data?.message||e.message||'Не удалось сохранить';if(e?.statusCode===409)await query.refetch()}}
 finally{busy.value=false;uploadStatus.value=''}
}
async function remove(attachmentId?:string){
 if(busy.value)return;const user=auth.user?.id;busy.value=true;error.value=''
 try{const result=await sharedRequest<ProjectInputs>(base.value,{method:'DELETE',body:{revision:attachmentId?draftRevision.value:query.data.value?.revision,id:attachmentId?draft.value.id:removeId.value,...(attachmentId?{attachmentId}:{})}});if(auth.user?.id!==user)return;client.setQueryData(key.value,result);draftRevision.value=result.revision;existing.value=result.cards.find(c=>c.id===draft.value.id)?.attachments??[];removeId.value='';await refreshRelated()}
 catch(e:any){if(auth.user?.id===user){error.value=e?.data?.message||'Не удалось удалить';if(e?.statusCode===409)await query.refetch()}}finally{busy.value=false}
}
async function download(file:InputAttachment,show=false){
 if(loadingFile.value)return;const user=auth.user?.id;loadingFile.value=file.id;error.value=''
 try{const blob=await sharedRequest<Blob>(`${base.value}/file?file=${file.id}`);if(auth.user?.id!==user)return
 const url=URL.createObjectURL(new Blob([blob],{type:show&&image(file)?file.type:'application/octet-stream'}))
 if(show&&image(file)){clearPreview();preview.value=url;previewName.value=file.name}else{const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}}
 catch(e:any){if(auth.user?.id===user)error.value=e?.data?.message||'Не удалось открыть файл'}finally{loadingFile.value=''}
}
function clearPreview(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value=''}
watch(()=>auth.user?.id,()=>{clearPreview();open.value=false;draft.value={id:'',title:'',description:'',fields:[]};files.value=[];existing.value=[];removeId.value=''})
onBeforeUnmount(clearPreview)
</script>
<template>
 <section class="project-input-data" aria-label="Входные данные проекта">
  <div class="input-toolbar"><UInput v-model="search" icon="i-lucide-search" placeholder="Найти карточку, поле или файл" aria-label="Поиск по входным данным" class="input-search"/><span v-if="query.data.value" class="input-count">Карточек: {{query.data.value.cards.length}}</span><UButton v-if="canEdit" label="Добавить карточку" icon="i-lucide-plus" :disabled="!query.data.value" @click="edit()"/></div>
  <UAlert v-if="error&&!open&&!removeId" color="error" :description="error" class="mb-5"/>
  <p v-if="query.isPending.value" class="input-state">Загружаем входные данные…</p>
  <UAlert v-else-if="query.error.value" title="Не удалось загрузить входные данные" color="error" :actions="[{label:'Повторить',onClick:()=>query.refetch()}]"/>
  <div v-else-if="!rows.length" class="input-empty"><UIcon name="i-lucide-folder-input"/><h2>{{search?'Карточки не найдены':'Всё, с чего начинается проект'}}</h2><p>{{search?'Попробуйте другое название или значение поля.':'Добавьте информацию от заказчика, требования, фотографии и документы. Карточки помогут собрать материалы в одном месте.'}}</p><UButton v-if="canEdit&&!search" label="Добавить первую карточку" icon="i-lucide-plus" @click="edit()"/></div>
  <div v-else class="input-card-grid"><article v-for="card in rows" :key="card.id" class="input-card"><header><span class="input-card-icon"><UIcon name="i-lucide-notebook-tabs"/></span><small>Обновлено {{date(card.updatedAt)}}</small><UButton v-if="canEdit" icon="i-lucide-pencil" color="neutral" variant="ghost" :aria-label="`Изменить: ${card.title}`" @click="edit(card)"/></header><h2>{{card.title}}</h2><p v-if="card.description" class="input-description">{{card.description}}</p><dl v-if="card.fields.length" class="input-fields"><template v-for="field in card.fields" :key="field.id"><dt>{{field.label}}</dt><dd><a v-if="field.type==='url'&&field.value" :href="field.value" target="_blank" rel="noopener noreferrer">{{field.value}} ↗</a><span v-else-if="field.type==='checkbox'">{{field.value==='true'?'Да':'Нет'}}</span><span v-else>{{field.value||'—'}}</span></dd></template></dl><div v-if="card.attachments.length" class="input-attachments"><h3>Вложения · {{card.attachments.length}}</h3><div v-for="file in card.attachments" :key="file.id" class="input-file"><UIcon :name="image(file)?'i-lucide-image':'i-lucide-file-text'"/><span><strong>{{file.name}}</strong><small>{{size(file.size)}}</small></span><UButton v-if="image(file)" icon="i-lucide-eye" color="neutral" variant="ghost" :aria-label="`Посмотреть ${file.name}`" :disabled="!!loadingFile" @click="download(file,true)"/><UButton icon="i-lucide-download" color="neutral" variant="ghost" :aria-label="`Скачать ${file.name}`" :loading="loadingFile===file.id" :disabled="!!loadingFile" @click="download(file)"/></div></div><footer v-if="canEdit"><UButton label="Удалить карточку" icon="i-lucide-trash-2" color="neutral" variant="ghost" size="sm" @click="removeId=card.id;error=''"/></footer></article></div>
  <UModal v-model:open="open" :title="query.data.value?.cards.some(c=>c.id===draft.id)?'Изменить карточку':'Новая карточка'" description="Информация о проекте, дополнительные поля и вложения." :dismissible="!busy" :ui="{content:'sm:max-w-3xl'}"><template #body><form class="input-form" @submit.prevent="save"><UFormField label="Название" required><UInput v-model="draft.title" class="w-full" :maxlength="160" required :disabled="busy"/></UFormField><UFormField label="Информация / описание"><UTextarea v-model="draft.description" class="w-full" :rows="5" :maxlength="30000" :disabled="busy"/></UFormField><div class="input-section-title"><h3>Дополнительные поля</h3><UButton label="Добавить поле" icon="i-lucide-plus" color="neutral" variant="outline" size="sm" :disabled="busy||draft.fields.length>=50" @click="addField"/></div><div v-for="(field,index) in draft.fields" :key="field.id" class="input-field-editor"><div><UInput v-model="field.label" placeholder="Название поля" aria-label="Название дополнительного поля" class="w-full" :maxlength="120" required :disabled="busy"/><USelect :model-value="field.type" :items="types" aria-label="Тип поля" :disabled="busy" @update:model-value="value=>fieldType(field,value as InputFieldType)"/><UButton icon="i-lucide-x" color="neutral" variant="ghost" aria-label="Убрать поле" :disabled="busy" @click="draft.fields.splice(index,1)"/></div><UTextarea v-if="field.type==='multiline'" v-model="field.value" aria-label="Значение поля" class="w-full" :disabled="busy" :maxlength="10000"/><UCheckbox v-else-if="field.type==='checkbox'" :model-value="field.value==='true'" label="Да" :disabled="busy" @update:model-value="value=>field.value=String(!!value)"/><UInput v-else v-model="field.value" :type="field.type==='url'?'url':field.type==='date'?'date':field.type==='number'?'number':'text'" :step="field.type==='number'?'any':undefined" aria-label="Значение поля" class="w-full" :maxlength="10000" :disabled="busy"/></div><div class="input-section-title"><h3>Вложения</h3><UButton label="Выбрать файлы" icon="i-lucide-paperclip" color="neutral" variant="outline" size="sm" :disabled="busy" @click="fileInput?.click()"/></div><input ref="fileInput" type="file" multiple class="sr-only" aria-label="Файлы карточки" :disabled="busy" @change="chooseFiles"/><p class="input-hint">Документы, PDF, фотографии, таблицы и другие файлы. До 20 МБ на файл, до 50 вложений в карточке. Файлы загружаются после нажатия «Сохранить».</p><div v-for="file in existing" :key="file.id" class="input-file"><UIcon name="i-lucide-file"/><span>{{file.name}}<small>{{size(file.size)}}</small></span><UButton icon="i-lucide-trash-2" color="neutral" variant="ghost" :aria-label="`Удалить вложение ${file.name}`" :disabled="busy" @click="remove(file.id)"/></div><div v-for="(file,index) in files" :key="index" class="input-file"><UIcon name="i-lucide-upload"/><span>{{file.name}}<small>{{size(file.size)}} · Будет загружен</small></span><UButton icon="i-lucide-x" color="neutral" variant="ghost" aria-label="Убрать выбранный файл" :disabled="busy" @click="files.splice(index,1)"/></div><UAlert v-if="error" color="error" :description="error"/><p v-if="uploadStatus" class="input-hint" role="status">{{uploadStatus}}</p><div class="input-form-actions"><UButton label="Отмена" color="neutral" variant="outline" :disabled="busy" @click="open=false"/><UButton type="submit" label="Сохранить" :loading="busy" :disabled="!draft.title.trim()"/></div></form></template></UModal>
  <UModal :open="!!removeId" title="Удалить карточку?" description="Карточка и её вложения будут удалены из проекта." :dismissible="!busy" @update:open="value=>{if(!value)removeId=''}"><template #body><UAlert v-if="error" color="error" :description="error"/><div class="input-form-actions"><UButton label="Отмена" color="neutral" variant="outline" :disabled="busy" @click="removeId=''"/><UButton label="Удалить" color="error" :loading="busy" @click="remove()"/></div></template></UModal>
  <UModal :open="!!preview" :title="previewName" description="Просмотр изображения из карточки проекта." :ui="{content:'sm:max-w-4xl'}" @update:open="value=>{if(!value)clearPreview()}"><template #body><img v-if="preview" :src="preview" :alt="previewName" class="input-preview"/></template></UModal>
 </section>
</template>
<style scoped>
.input-toolbar{display:flex;align-items:center;gap:16px;margin-bottom:26px;flex-wrap:wrap}.input-search{flex:1;min-width:240px}.input-count,.input-hint,.input-state{font-size:12px;color:#94a3b8;line-height:1.7}.input-card-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;align-items:start}.input-card{padding:26px;border:1px solid #e2e8f0;border-radius:22px;background:#ffffffd9;min-width:0}.input-card header{display:flex;align-items:center;gap:12px}.input-card header small{flex:1;color:#94a3b8;font-size:10px}.input-card-icon{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:#f3f2f7;color:var(--ui-primary);font-size:21px}.input-card h2{font-size:21px;color:#334155;font-weight:600;margin:20px 0 14px;overflow-wrap:anywhere}.input-description{white-space:pre-wrap;font-size:13px;line-height:1.9;color:#64748b;overflow-wrap:anywhere}.input-fields{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.5fr);gap:12px 20px;margin-top:22px;font-size:12px;line-height:1.8}.input-fields dt{color:#94a3b8}.input-fields dd{color:#475569;white-space:pre-wrap;overflow-wrap:anywhere}.input-fields a{color:var(--ui-primary);text-decoration:underline}.input-attachments{border-top:1px solid #e2e8f0;margin-top:24px;padding-top:20px}.input-attachments h3,.input-section-title h3{font-size:13px;font-weight:600;color:#475569}.input-file{display:flex;align-items:center;gap:10px;padding:10px 0;font-size:12px;color:#64748b;min-width:0}.input-file>.iconify{font-size:19px;flex-shrink:0;color:#94a3b8}.input-file>span{flex:1;min-width:0;overflow-wrap:anywhere}.input-file strong{font-weight:500}.input-file small{display:block;font-size:10px;color:#94a3b8;margin-top:4px}.input-card footer{border-top:1px solid #edf0f5;margin-top:20px;padding-top:10px}.input-empty{text-align:center;padding:65px 25px;border:1px solid #e2e8f0;border-radius:24px;background:#ffffffb0}.input-empty>.iconify{font-size:36px;color:var(--ui-primary)}.input-empty h2{font-size:23px;color:#475569;margin:20px 0 12px}.input-empty p{font-size:14px;line-height:1.9;color:#94a3b8;max-width:600px;margin:0 auto 25px}.input-form{display:grid;gap:20px}.input-section-title{display:flex;justify-content:space-between;align-items:center;gap:12px}.input-field-editor{display:grid;gap:12px;padding:16px;border:1px solid #e2e8f0;border-radius:12px;background:#f8fafc}.input-field-editor>div:first-child{display:flex;gap:10px;align-items:center}.input-form-actions{display:flex;gap:12px;justify-content:flex-end;margin-top:15px}.input-preview{display:block;max-height:75vh;max-width:100%;margin:auto;object-fit:contain}@media(max-width:850px){.input-card-grid{grid-template-columns:1fr}}@media(max-width:600px){.input-card{padding:20px}.input-toolbar>button{width:100%;justify-content:center}.input-search{min-width:100%}.input-field-editor>div:first-child{flex-wrap:wrap}}
</style>
